import{_ as o,a0 as p,w as h,s as d,ao as l,I as n,x as t,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"你使用過 Python 3.6 中針對文件系統的這個神奇方法嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"你使用過 Python 3.6 中針對文件系統的這個神奇方法嗎？ | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"你使用過 Python 3.6 中針對文件系統的這個神奇方法嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你使用過 Python 3.6 中針對文件系統的這個神奇方法嗎？ | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210518 Are you using this magic method for filesystems from Python 3.6","title":"你使用過 Python 3.6 中針對文件系統的這個神奇方法嗎？","tag":"202106","desc":""},"relativePath":"202106/20210518 Are you using this magic method for filesystems from Python 3.6.md","filePath":"[post].md"}'),r={name:"202106/20210518 Are you using this magic method for filesystems from Python 3.6.md"};function u(g,s,f,k,c,b){const a=p("Link");return h(),d("div",null,[s[24]||(s[24]=l(`<h1 id="你使用過-python-3-6-中針對文件系統的這個神奇方法嗎" tabindex="-1">你使用過 Python 3.6 中針對文件系統的這個神奇方法嗎？ <a class="header-anchor" href="#你使用過-python-3-6-中針對文件系統的這個神奇方法嗎" aria-label="Permalink to “你使用過 Python 3.6 中針對文件系統的這個神奇方法嗎？”">​</a></h1><blockquote><p>探索 os.fspath 和其他兩個未被充分利用但仍然有用的 Python 特性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/03/164403a6m2c989hh963lm6.jpg" alt=""></p><p>這是 Python 3.x 首發特性系列文章中的第七篇。Python 3.6 首次發佈於 2016 年，儘管它已經發布了一段時間，但它引入的許多特性都沒有得到充分利用，而且相當酷。下面是其中的三個。</p><h3 id="分隔數字常數" tabindex="-1">分隔數字常數 <a class="header-anchor" href="#分隔數字常數" aria-label="Permalink to “分隔數字常數”">​</a></h3><p>快回答哪個更大，<code>10000000</code> 還是 <code>200000</code>？你在看代碼時能正確回答嗎？根據當地的習慣，在寫作中，你會用 10,000,000 或 10.000.000 來表示第一個數字。問題是，Python 使用逗號和句號是用於其他地方。</p><p>幸運的是，從 Python 3.6 開始，你可以使用下劃線來分隔數字。這在代碼中和使用字符串的 <code>int()</code> 轉換器時都可以使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import math</span></span>
<span class="line"><span>math.log(10_000_000) / math.log(10)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    7.0</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>math.log(int(&quot;10_000_000&quot;)) / math.log(10)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    7.0</span></span></code></pre></div><h3 id="tau-是對的" tabindex="-1">Tau 是對的 <a class="header-anchor" href="#tau-是對的" aria-label="Permalink to “Tau 是對的”">​</a></h3>`,12)),n("p",null,[s[1]||(s[1]=t("45 度角用弧度表示是多少？一個正確的答案是 ",-1)),s[2]||(s[2]=n("code",null,"π/4",-1)),s[3]||(s[3]=t("，但這有點難記。記住 45 度角是一個八分之一的轉角要容易得多。正如 ",-1)),e(a,{href:"https://tauday.com/tau-manifesto"},{default:i(()=>[...s[0]||(s[0]=[t("Tau Manifesto",-1)])]),_:1}),s[4]||(s[4]=t(" 所解釋的，",-1)),s[5]||(s[5]=n("code",null,"2π",-1)),s[6]||(s[6]=t("，稱為 ",-1)),s[7]||(s[7]=n("code",null,"Τ",-1)),s[8]||(s[8]=t("，是一個更自然的常數。",-1))]),s[25]||(s[25]=l(`<p>在 Python 3.6 及以後的版本中，你的數學代碼可以使用更直觀的常數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print(&quot;Tan of an eighth turn should be 1, got&quot;, round(math.tan(math.tau/8), 2))</span></span>
<span class="line"><span>print(&quot;Cos of an sixth turn should be 1/2, got&quot;, round(math.cos(math.tau/6), 2))</span></span>
<span class="line"><span>print(&quot;Sin of a quarter turn should be 1, go&quot;, round(math.sin(math.tau/4), 2))</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    Tan of an eighth turn should be 1, got 1.0</span></span>
<span class="line"><span>    Cos of an sixth turn should be 1/2, got 0.5</span></span>
<span class="line"><span>    Sin of a quarter turn should be 1, go 1.0</span></span></code></pre></div><h3 id="os-fspath" tabindex="-1">os.fspath <a class="header-anchor" href="#os-fspath" aria-label="Permalink to “os.fspath”">​</a></h3><p>從 Python 3.6 開始，有一個神奇的方法表示“轉換為文件系統路徑”。當給定一個 <code>str</code> 或 <code>bytes</code> 時，它返回輸入。</p><p>對於所有類型的對象，它尋找 <code>__fspath__</code> 方法並調用它。這允許傳遞的對象是“帶有元數據的文件名”。</p><p>像 <code>open()</code> 或 <code>stat</code> 這樣的普通函數仍然能夠使用它們，只要 <code>__fspath__</code> 返回正確的東西。</p><p>例如，這裏有一個函數將一些數據寫入一個文件，然後檢查其大小。它還將文件名記錄到標準輸出，以便追蹤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def write_and_test(filename):</span></span>
<span class="line"><span>    print(&quot;writing into&quot;, filename)</span></span>
<span class="line"><span>    with open(filename, &quot;w&quot;) as fpout:</span></span>
<span class="line"><span>        fpout.write(&quot;hello&quot;)</span></span>
<span class="line"><span>    print(&quot;size of&quot;, filename, &quot;is&quot;, os.path.getsize(filename))</span></span></code></pre></div><p>你可以用你期望的方式來調用它，用一個字符串作為文件名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>write_and_test(&quot;plain.txt&quot;)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    writing into plain.txt</span></span>
<span class="line"><span>    size of plain.txt is 5</span></span></code></pre></div><p>然而，可以定義一個新的類，為文件名的字符串表示法添加信息。這樣可以使日誌記錄更加詳細，而不改變原來的功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class DocumentedFileName:</span></span>
<span class="line"><span>    def __init__(self, fname, why):</span></span>
<span class="line"><span>        self.fname = fname</span></span>
<span class="line"><span>        self.why = why</span></span>
<span class="line"><span>    def __fspath__(self):</span></span>
<span class="line"><span>        return self.fname</span></span>
<span class="line"><span>    def __repr__(self):</span></span>
<span class="line"><span>        return f&quot;DocumentedFileName(fname={self.fname!r}, why={self.why!r})&quot;</span></span></code></pre></div><p>用 <code>DocumentedFileName</code> 實例作為輸入運行該函數，允許 <code>open</code> 和 <code>os.getsize</code> 函數繼續工作，同時增強日誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>write_and_test(DocumentedFileName(&quot;documented.txt&quot;, &quot;because it&#39;s fun&quot;))</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    writing into DocumentedFileName(fname=&#39;documented.txt&#39;, why=&quot;because it&#39;s fun&quot;)</span></span>
<span class="line"><span>    size of DocumentedFileName(fname=&#39;documented.txt&#39;, why=&quot;because it&#39;s fun&quot;) is 5</span></span></code></pre></div><h3 id="歡迎來到-2016-年" tabindex="-1">歡迎來到 2016 年 <a class="header-anchor" href="#歡迎來到-2016-年" aria-label="Permalink to “歡迎來到 2016 年”">​</a></h3><p>Python 3.6 是在五年前發佈的，但是在這個版本中首次出現的一些特性非常酷，而且沒有得到充分利用。如果你還沒使用，那麼將他們添加到你的工具箱中。</p><hr>`,20)),n("p",null,[s[10]||(s[10]=t("via: ",-1)),e(a,{href:"https://opensource.com/article/21/5/python-36-features"},{default:i(()=>[...s[9]||(s[9]=[t("https://opensource.com/article/21/5/python-36-features",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=t("作者：",-1)),e(a,{href:"https://opensource.com/users/moshez"},{default:i(()=>[...s[11]||(s[11]=[t("Moshe Zadka",-1)])]),_:1}),s[16]||(s[16]=t(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[12]||(s[12]=[t("lujun9972",-1)])]),_:1}),s[17]||(s[17]=t(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[13]||(s[13]=[t("geekpi",-1)])]),_:1}),s[18]||(s[18]=t(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[14]||(s[14]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[21]||(s[21]=t("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[19]||(s[19]=[t("LCTT",-1)])]),_:1}),s[22]||(s[22]=t(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[20]||(s[20]=[t("Linux中國",-1)])]),_:1}),s[23]||(s[23]=t(" 榮譽推出",-1))])])}const x=o(r,[["render",u]]);export{C as __pageData,x as default};
